const root = $json && typeof $json === 'object' && !Array.isArray($json) ? $json : {};
const req = root.session_request && typeof root.session_request === 'object' ? root.session_request : {};
const operation = String(req.operation ?? '').trim();
const errors = [];
if (!['read_session','upsert_session','update_chapter','clear_session'].includes(operation)) errors.push('session_request.operation must be read_session, upsert_session, update_chapter, or clear_session.');
const telegram_user_id = String(req.telegram_user_id ?? '').trim();
const telegram_chat_id = String(req.telegram_chat_id ?? '').trim();
if (!telegram_user_id) errors.push('telegram_user_id is required.');
if (!telegram_chat_id) errors.push('telegram_chat_id is required.');
const session = req.session && typeof req.session === 'object' && !Array.isArray(req.session) ? req.session : {};
return [{ json: { operation, telegram_user_id, telegram_chat_id, session, is_valid: errors.length === 0, validation_errors: errors } }];

const prior = $('Validate Session Request').item.json;
const rows = $input.all().map(i => i.json).filter(r => r && Object.keys(r).length);
const row = rows[0] || {};
const found = Boolean(row.telegram_user_id || row.active_workspace_uuid || row.workspace_folder_id);
return [{ json: { schema_version:'1.0', workflow_version:'1.0', route:'session.completed', target:'WF-000', status: prior.is_valid ? 'ready' : 'error', is_valid: prior.is_valid, validation_errors: prior.validation_errors || [], session_found: found, session: found ? { telegram_user_id:String(row.telegram_user_id ?? prior.telegram_user_id), telegram_chat_id:String(row.telegram_chat_id ?? prior.telegram_chat_id), active_novel_uuid:String(row.active_novel_uuid ?? ''), active_workspace_uuid:String(row.active_workspace_uuid ?? ''), storage_root_id:String(row.storage_root_id ?? ''), project_folder_id:String(row.project_folder_id ?? ''), workspace_folder_id:String(row.workspace_folder_id ?? ''), workspace_version:String(row.workspace_version ?? ''), active_chapter_number:String(row.active_chapter_number ?? ''), updated_at:String(row.updated_at ?? '') } : {} } }];
